package com.vit.archds.entity; import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="quality_evaluations") public class QualityEvaluation { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="candidate_id") private ArchitectureCandidate candidate; @Lob @Column(nullable=false) private String scoresJson; @Column(nullable=false) private Double weightedScore; @Lob private String reasoningJson; @Column(nullable=false) private Instant createdAt=Instant.now(); public QualityEvaluation(){} public QualityEvaluation(ArchitectureCandidate c,String s,Double w,String r){candidate=c;scoresJson=s;weightedScore=w;reasoningJson=r;} }
